bun -e '
import {fold} from "./src/fold.ts";
import {readEvents} from "./src/log.ts";
const g=fold(readEvents());
const n=g.nodes.get("lp-prod-judge");
console.log(JSON.stringify(n.body));
'

cat > /tmp/judge-ops.json << 'EOF'
[
  {
    "tag": "elaborated",
    "old": "    every acceptance criterion has a test that fails without the change\n    each I/O module touched still meets its named behaviour list\n    no new exported function in src/ without a doc comment naming its card\n    no code path rewrites or deletes a line of .werk/log.jsonl\n    card text is never mutated outside the CLI (#werk-write)",
    "new": "- every acceptance criterion has a test that fails without the change\n- each I/O module touched still meets its named behaviour list\n- no new exported function in src/ without a doc comment naming its card\n- no code path rewrites or deletes a line of .werk/log.jsonl\n- card text is never mutated outside the CLI (#werk-write)"
  }
]
EOF
node src/cli.ts propose lp-prod-judge --ops "$(cat /tmp/judge-ops.json)" 2>&1

bun -e '
import {fold} from "./src/fold.ts";
import {readEvents} from "./src/log.ts";
import {writeFileSync} from "fs";
const g=fold(readEvents());
const body=g.nodes.get("lp-prod-judge").body??"";
const blocks=String(body).split(/\n\s*\n/).map(s=>s.trim()).filter(Boolean);
writeFileSync("/tmp/judge-blocks.json",JSON.stringify(blocks,null,2));
console.log(blocks.length+" blocks");
blocks.forEach((b,i)=>console.log(i+": "+JSON.stringify(b.slice(0,60))));
'

